  Lemma chk4_fast : forall regs, (N <= 64)%Z ->
    getr regs 10 = Z_to_bv 64 res -> getr regs 9 = Z_to_bv 64 N -> getr regs 18 = Z_to_bv 64 p ->
    exists regs',
      msteps ASEGS (mkst regs (0x6eae0 : word) M rom) (mkst regs' (0x6eb28 : word) M rom)
