Section CHKQ.
  Variable M rom : word -> option byte.
  Variables p N res size : Z.
  Hypothesis Hp64 : (p mod 64 = 32)%Z.
  Hypothesis Hp : (0x6b6000 <= p)%Z /\ (p + 100 <= 2 ^ 47)%Z.
  Hypothesis Hpa : (p + 100 <= 0x7fff7000 \/ 0x10007fff8000 <= p)%Z.      (* [comment removed for export] *)
