  Hypothesis Hres : (0 <= res < 2 ^ 31 - 1)%Z.
  Hypothesis Hsize : (0 < size < 2 ^ 63)%Z.
  Hypothesis HNdef : N = Z.min size (res + 1).
  Hypothesis HG : rt_layout_globs M.
