  Variable q : Z.
  Hypothesis Hq : (0 < q < 2 ^ 64)%Z.
  Hypothesis HQ : rdn ASEGS M (Z_to_bv 64 (SB + p / 8 - 4)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 q)).
