  Hypothesis HZ : forall i, (0 <= i < 4)%Z -> M (Z_to_bv 64 (SB + p / 8 + i)) = Some (Z_to_bv 8 0).

  Let fS := (SB + p / 8)%Z.
  Let g := ((N - 1) / 8)%Z.

  Lemma pq_facts : (p / 8 = 8 * (p / 64) + 4)%Z /\ (0 <= g <= 3)%Z /\ ((p + N - 1) / 8 = p / 8 + g)%Z /\ (fS mod 8 = 4)%Z
